  1	// src/lib/rechner/annahmen.js
  2	//
  3	// Formatierung für alle Rechner. Die fachlichen Marktannahmen stehen in
  4	// src/lib/invest/markt.js – hier nur Zahlenformate (de-DE).
  5	
  6	export { STAND } from "../invest/markt.js";
  7	
  8	export const fmt = (n, stellen = 0) =>
  9	  Number.isFinite(n) ? n.toLocaleString("de-DE", { minimumFractionDigits: stellen, maximumFractionDigits: stellen }) : "–";
 10	export const fmtEur = (n) => `${fmt(Math.round(n))} €`;
 11	export const fmtMio = (n, stellen = 1) => `${fmt(n / 1e6, stellen)} Mio. €`;
 12	export const fmtPct = (n, stellen = 1) => `${fmt(n * 100, stellen)} %`;
 13	export const fmtCt = (n, stellen = 1) => `${fmt(n, stellen)} ct/kWh`;
 14	// src/lib/rechner/solarpark.js
 15	//
 16	// Renditerechnung eines Solarparks über die gesamte Laufzeit – reine Logik
 17	// ohne React, damit Rechner, Hub-Vorschau und Selbsttest dieselben Zahlen
 18	// liefern. Alle Standardwerte kommen aus src/lib/invest/markt.js.
 19	//
 20	// Methodik (bewusst einfach und offen gelegt):
 21	//  - Jahreswerte, Jahr 0 = Investition, Jahr 1 … Laufzeit = Betrieb
 22	//  - Erzeugung: Regionsertrag × Bauartfaktor, jährliche Degradation
 23	//  - Erlöse: Vertragsphase und danach Marktwert (Merchant, heutiger Preis,
 24	//    fortgeschrieben mit der Marktwert-Steigerung). EEG-Zuschlag wirkt im
 25	//    Marktprämienmodell als Untergrenze: Liegt der Marktwert darüber, bleibt
 26	//    der Marktwert. Ein PPA ist ein nominal fester Preis.
 27	//  - Kosten: Betriebskosten + Pacht (beide mit Inflation), Rückbau-Rücklage
 28	//  - Finanzierung: Annuitätendarlehen über die Tilgungsdauer; optional wird
 29	//    das Darlehen wie bei Banken üblich auf eine Mindest-DSCR begrenzt
 30	//  - Renditen vor Steuern (Projekt- und Eigenkapital-IRR)
 31	//  - LCOE nominal: konstanter Strompreis, bei dem der Kapitalwert zum WACC null ist
 32	
 33	import { FREIFLAECHE, ERLOESE, FINANZIERUNG, PACHT, BAUART, regionById, npv, irr, annuitaet } from "../invest/markt.js";
 34	
 35	export const ERLOESMODELLE = {
 36	  eeg: { label: "EEG-Zuschlag", kurz: "EEG", vertragJahre: 20, preisCt: ERLOESE.eegFreiflaecheCt },
 37	  ppa: { label: "PPA", kurz: "PPA", vertragJahre: 10, preisCt: ERLOESE.ppaCt.mittel },
 38	  merchant: { label: "Merchant", kurz: "Markt", vertragJahre: 0, preisCt: ERLOESE.merchantCt },
 39	};
 40	
 41	export const STANDARD = {
 42	  mwp: 10,
 43	  regionId: "de-sued",
 44	  bauart: "sued",
 45	  capexKwp: FREIFLAECHE.capexProKwp.mittel,
 46	  entwicklungKwp: FREIFLAECHE.entwicklungProKwp.min,
 47	  netzKm: 1,
 48	  modell: "eeg",
 49	  preisCt: ERLOESE.eegFreiflaecheCt,
 50	  vertragJahre: 20,
 51	  merchantCt: ERLOESE.merchantCt,
 52	  merchantSteigerung: ERLOESE.merchantSteigerung,
 53	  pachtHa: PACHT.freiflaecheProHa.mittel,
 54	  opexKwp: FREIFLAECHE.opexProKwp,
 55	  degradation: FREIFLAECHE.degradation,
 56	  fkQuote: FINANZIERUNG.fremdkapitalQuote,
 57	  zins: FINANZIERUNG.zins,
 58	  tilgungJahre: FINANZIERUNG.tilgungJahre,
 59	  laufzeit: FREIFLAECHE.laufzeit,
 60	  inflation: FREIFLAECHE.inflation,
 61	  ekRendite: FINANZIERUNG.diskont,
 62	  /** Darlehen auf Mindest-DSCR begrenzen (Bankpraxis) */
 63	  dscrBegrenzen: true,
 64	  dscrZiel: FINANZIERUNG.dscrZiel,
 65	};
 66	
 67	/** Investitionsbausteine in € */
 68	export function investition({ mwp, capexKwp, entwicklungKwp = 0, netzKm = 0 }) {
 69	  const kwp = mwp * 1000;
 70	  const anlage = kwp * capexKwp;
 71	  const netz = mwp * FREIFLAECHE.netzanschlussFixProMwp + netzKm * 1000 * FREIFLAECHE.kabelProMeter;
 72	  const entwicklung = kwp * entwicklungKwp;
 73	  return { anlage, netz, entwicklung, summe: anlage + netz + entwicklung };
 74	}
 75	
 76	/**
 77	 * Hauptrechnung. Alle Parameter optional (Standard aus STANDARD).
 78	 * Preise in ct/kWh, Quoten als Anteil (0,75), Zins als Anteil (0,045).
 79	 */
 80	export function rechneSolarpark(eingabe = {}) {
 81	  const e = { ...STANDARD, ...eingabe };
 82	  const kwp = e.mwp * 1000;
 83	  const region = regionById(e.regionId);
 84	  const bauart = BAUART[e.bauart] || BAUART.sued;
 85	  // Optional: spezifischer Ertrag aus einem Ertragsgutachten (z. B. P50/P90 aus dem Projektdatenblatt der Börse)
 86	  const spezErtrag = e.spezErtrag > 0 ? e.spezErtrag : region.ertrag * bauart.faktor;
 87	  const flaecheHa = e.mwp * bauart.haProMwp;
 88	  const inv = investition(e);
 89	  const vertragJahre = e.modell === "merchant" ? 0 : Math.min(e.vertragJahre, e.laufzeit);
 90	
 91	  // Erzeugung und operativer Cashflow (unabhängig von der Finanzierung)
 92	  const betrieb = [];
 93	  for (let t = 1; t <= e.laufzeit; t++) {
 94	    const erzeugung = kwp * spezErtrag * Math.pow(1 - e.degradation, t - 1); // kWh
 95	    const indexiert = Math.pow(1 + e.inflation, t - 1);
 96	    const marktCt = e.merchantCt * Math.pow(1 + e.merchantSteigerung, t - 1);
 97	    const imVertrag = t <= vertragJahre;
 98	    const preisCt = !imVertrag ? marktCt : e.modell === "eeg" ? Math.max(e.preisCt, marktCt) : e.preisCt;
 99	    const erloes = (erzeugung * preisCt) / 100;
100	    const opex = kwp * e.opexKwp * indexiert;
101	    const pacht = flaecheHa * e.pachtHa * Math.pow(1 + PACHT.indexierung, t - 1);
102	    const rueckbau = (kwp * FREIFLAECHE.rueckbauProKwp) / e.laufzeit;
103	    const kosten = opex + pacht + rueckbau;
104	    betrieb.push({ jahr: t, erzeugung, preisCt, marktCt, imVertrag, erloes, opex, pacht, rueckbau, kosten, ebitda: erloes - kosten });
105	  }
106	
107	  // Fremdkapital: gewünschte Quote, ggf. begrenzt durch die Mindest-DSCR
108	  const tilgungJahre = Math.min(e.tilgungJahre, e.laufzeit);
109	  const fkWunsch = inv.summe * e.fkQuote;
110	  const faktor = annuitaet(1, e.zins, tilgungJahre); // Rate je 1 € Darlehen
111	  const minCfads = Math.min(...betrieb.slice(0, tilgungJahre).map((b) => b.ebitda));
112	  const fkMax = minCfads > 0 ? minCfads / e.dscrZiel / faktor : 0;
113	  const fkBegrenzt = e.dscrBegrenzen && fkWunsch > fkMax;
114	  const fk = fkBegrenzt ? fkMax : fkWunsch;
115	  const fkQuoteEff = inv.summe > 0 ? fk / inv.summe : 0;
116	  const ek = inv.summe - fk;
117	  const rate = fk > 0 ? fk * faktor : 0;
118	  // Kapitalkosten für Barwert und LCOE aus der Zielstruktur (unabhängig davon,
119	  // ob die Bank das Darlehen kürzt) – so bleibt die LCOE vom Erlös unabhängig.
120	  const wacc = e.fkQuote * e.zins + (1 - e.fkQuote) * e.ekRendite;
121	
122	  const jahre = [];
123	  let restschuld = fk;
124	  for (const b of betrieb) {
125	    const t = b.jahr;
126	    const { ebitda } = b;
127	    let zinsen = 0;
128	    let tilgung = 0;
129	    if (restschuld > 0.5 && t <= tilgungJahre) {
130	      zinsen = restschuld * e.zins;
131	      tilgung = Math.min(rate - zinsen, restschuld);
132	      restschuld -= tilgung;
133	    }
134	    const schuldendienst = zinsen + tilgung;
135	    jahre.push({
136	      ...b,
137	      zinsen,
138	      tilgung,
139	      schuldendienst,
140	      cfProjekt: ebitda,
141	      cfEk: ebitda - schuldendienst,
142	      dscr: schuldendienst > 0 ? ebitda / schuldendienst : null,
143	      restschuld: Math.max(restschuld, 0),
144	    });
145	  }
146	
147	  const cfProjekt = [-inv.summe, ...jahre.map((j) => j.cfProjekt)];
148	  const cfEk = [-ek, ...jahre.map((j) => j.cfEk)];
149	  const projektIrr = irr(cfProjekt);
150	  const ekIrr = ek > 0 ? irr(cfEk) : null;
151	  const kapitalwert = npv(wacc, cfProjekt);
152	  const kapitalwertEk = npv(e.ekRendite, cfEk);
153	
154	  // LCOE nominal: Barwert Kosten / Barwert Erzeugung (Diskont = WACC)
155	  const bwKosten = inv.summe + jahre.reduce((s, j) => s + j.kosten / Math.pow(1 + wacc, j.jahr), 0);
156	  const bwEnergie = jahre.reduce((s, j) => s + j.erzeugung / Math.pow(1 + wacc, j.jahr), 0);
157	  const lcoeCt = (bwKosten / bwEnergie) * 100;
158	
159	  // Amortisation (Projekt, statisch-kumuliert, mit linearer Interpolation)
160	  let kum = -inv.summe;
161	  let amortisation = null;
162	  for (const j of jahre) {
163	    const vorher = kum;
164	    kum += j.cfProjekt;
165	    if (amortisation == null && kum >= 0) amortisation = j.jahr - 1 + (-vorher / j.cfProjekt);
166	  }
167	  let kumEk = -ek;
168	  let amortisationEk = null;
169	  for (const j of jahre) {
170	    const vorher = kumEk;
171	    kumEk += j.cfEk;
172	    if (amortisationEk == null && kumEk >= 0 && j.cfEk > 0) amortisationEk = j.jahr - 1 + (-vorher / j.cfEk);
173	  }
174	
175	  const mitDienst = jahre.filter((j) => j.dscr != null);
176	  const dscrMin = mitDienst.length ? Math.min(...mitDienst.map((j) => j.dscr)) : null;
177	  const dscrMittel = mitDienst.length ? mitDienst.reduce((s, j) => s + j.dscr, 0) / mitDienst.length : null;
178	
179	  const summe = (k) => jahre.reduce((s, j) => s + j[k], 0);
180	
181	  return {
182	    eingabe: e,
183	    kwp,
184	    region,
185	    bauart,
186	    spezErtrag,
187	    flaecheHa,
188	    ertragJahr1: jahre[0]?.erzeugung || 0,
189	    investition: inv,
190	    investProKwp: inv.summe / kwp,
191	    fk,
192	    fkWunsch,
193	    fkQuoteEff,
194	    fkBegrenzt,
195	    ek,
196	    rate,
197	    wacc,
198	    vertragJahre,
199	    jahre,
200	    projektIrr,
201	    ekIrr,
202	    kapitalwert,
203	    kapitalwertEk,
204	    lcoeCt,
205	    amortisation,
206	    amortisationEk,
207	    dscrMin,
208	    dscrMittel,
209	    summen: { erloes: summe("erloes"), kosten: summe("kosten"), schuldendienst: summe("schuldendienst"), cfEk: summe("cfEk"), erzeugung: summe("erzeugung") },
210	  };
211	}
212	
213	/**
214	 * Sensitivität: Projekt- und EK-IRR bei veränderten Investitionskosten
215	 * (Zeilen) und Strompreisen (Spalten, wirkt auf Vertrags- und Marktpreis).
216	 */
217	export function sensitivitaet(eingabe = {}, schritteCapex = [-0.1, -0.05, 0, 0.05, 0.1], schrittePreis = [-0.1, -0.05, 0, 0.05, 0.1]) {
218	  const e = { ...STANDARD, ...eingabe };
219	  return schritteCapex.map((dc) => ({
220	    capex: dc,
221	    capexKwp: e.capexKwp * (1 + dc),
222	    zellen: schrittePreis.map((dp) => {
223	      const r = rechneSolarpark({ ...e, capexKwp: e.capexKwp * (1 + dc), preisCt: e.preisCt * (1 + dp), merchantCt: e.merchantCt * (1 + dp) });
224	      return { preis: dp, projektIrr: r.projektIrr, ekIrr: r.ekIrr, dscrMin: r.dscrMin };
225	    }),
226	  }));
227	}
228	
229	/* ------------------------------------------------------------------ */
230	/* Selbsttest: node src/lib/rechner/solarpark.js                       */
231	/* ------------------------------------------------------------------ */
232	
233	export function selbsttest() {
234	  const fehler = [];
235	  const pruefe = (ok, text) => {
236	    if (!ok) fehler.push(text);
237	  };
238	
239	  const r = rechneSolarpark({ mwp: 10, regionId: "de-sued", bauart: "sued", capexKwp: 530, modell: "eeg", preisCt: 5, vertragJahre: 20 });
240	  pruefe(r.kwp === 10000, "10 MWp = 10.000 kWp");
241	  pruefe(Math.abs(r.ertragJahr1 - 11_000_000) < 1, "Ertrag Jahr 1: 10.000 kWp × 1.100 kWh/kWp = 11 GWh");
242	  pruefe(r.lcoeCt > 4.5 && r.lcoeCt < 6.5, `LCOE plausibel 4,5–6,5 ct (ist ${r.lcoeCt.toFixed(2)})`);
243	  pruefe(r.projektIrr > 0.02 && r.projektIrr < 0.09, `Projekt-IRR plausibel 2–9 % (ist ${(r.projektIrr * 100).toFixed(2)} %)`);
244	  pruefe(r.jahre.length === 30, "30 Betriebsjahre");
245	  pruefe(r.jahre[19].imVertrag && !r.jahre[20].imVertrag, "EEG endet nach Jahr 20");
246	  pruefe(Math.abs(r.jahre[r.eingabe.tilgungJahre - 1].restschuld) < 1, "Darlehen am Ende der Tilgungsdauer getilgt");
247	  pruefe(r.jahre[r.eingabe.tilgungJahre].schuldendienst === 0, "nach Tilgung kein Schuldendienst");
248	  pruefe(Math.abs(r.fk + r.ek - r.investition.summe) < 1, "FK + EK = Investition");
249	
250	  const teurer = rechneSolarpark({ mwp: 10, capexKwp: 600, preisCt: 5 });
251	  pruefe(teurer.projektIrr < r.projektIrr, "höhere Capex senken den IRR");
252	  const besser = rechneSolarpark({ mwp: 10, capexKwp: 530, preisCt: 6 });
253	  pruefe(besser.projektIrr > r.projektIrr, "höherer Preis erhöht den IRR");
254	  pruefe(Math.abs(besser.lcoeCt - r.lcoeCt) < 1e-9, "LCOE unabhängig vom Erlös");
255	  pruefe(r.dscrMin >= r.eingabe.dscrZiel - 1e-6, "Darlehen auf Mindest-DSCR begrenzt");
256	  const frei = rechneSolarpark({ mwp: 10, capexKwp: 530, preisCt: 5, dscrBegrenzen: false });
257	  pruefe(Math.abs(frei.fkQuoteEff - 0.75) < 1e-9, "ohne Begrenzung gilt die gewünschte FK-Quote");
258	  const eegBoden = rechneSolarpark({ mwp: 10, preisCt: 3, merchantCt: 5, merchantSteigerung: 0 });
259	  pruefe(Math.abs(eegBoden.jahre[0].preisCt - 5) < 1e-9, "EEG wirkt als Untergrenze: höherer Marktwert bleibt");
260	  const ppaFest = rechneSolarpark({ mwp: 10, modell: "ppa", preisCt: 3, vertragJahre: 10, merchantCt: 5, merchantSteigerung: 0 });
261	  pruefe(Math.abs(ppaFest.jahre[0].preisCt - 3) < 1e-9 && Math.abs(ppaFest.jahre[10].preisCt - 5) < 1e-9, "PPA fest, danach Marktwert");
262	
263	  const ohneFk = rechneSolarpark({ mwp: 10, capexKwp: 530, preisCt: 5, fkQuote: 0 });
264	  pruefe(Math.abs(ohneFk.ekIrr - ohneFk.projektIrr) < 1e-4, "ohne Fremdkapital: EK-IRR = Projekt-IRR");
265	  pruefe(ohneFk.dscrMin == null, "ohne Fremdkapital kein DSCR");
266	
267	  const lcoePreis = rechneSolarpark({ mwp: 10, capexKwp: 530, preisCt: 5, modell: "ppa", vertragJahre: 30 });
268	  const lcoeFall = rechneSolarpark({ mwp: 10, capexKwp: 530, modell: "ppa", preisCt: lcoePreis.lcoeCt, vertragJahre: 30 });
269	  pruefe(Math.abs(lcoeFall.projektIrr - lcoeFall.wacc) < 0.001, "Preis = LCOE über die ganze Laufzeit → Projekt-IRR = WACC");
270	
271	  const m = sensitivitaet({ mwp: 10, capexKwp: 530, preisCt: 5 });
272	  pruefe(m.length === 5 && m[0].zellen.length === 5, "Sensitivitätsmatrix 5 × 5");
273	  pruefe(m[0].zellen[4].projektIrr > m[4].zellen[0].projektIrr, "günstig + teurer Strom schlägt teuer + billiger Strom");
274	
275	  return { fehler, beispiel: r };
276	}
277	
278	if (typeof process !== "undefined" && process.argv?.[1] && /solarpark\.js$/.test(process.argv[1].replace(/\\/g, "/"))) {
279	  const { fehler, beispiel: r } = selbsttest();
280	  const p = (x) => (x == null ? "–" : `${(x * 100).toFixed(2)} %`);
281	  console.log(
282	    `Beispiel 10 MWp Süd, 530 €/kWp, EEG 5 ct: Invest ${Math.round(r.investProKwp)} €/kWp, LCOE ${r.lcoeCt.toFixed(2)} ct, ` +
283	      `Projekt-IRR ${p(r.projektIrr)}, EK-IRR ${p(r.ekIrr)}, DSCR min ${r.dscrMin?.toFixed(2)}, Amortisation ${r.amortisation?.toFixed(1)} J., WACC ${p(r.wacc)}`
284	  );
285	  if (fehler.length) {
286	    console.error("FEHLER:\n- " + fehler.join("\n- "));
287	    process.exit(1);
288	  }
289	  console.log("Selbsttest solarpark.js: alle Prüfungen bestanden.");
290	}

