  8	/** Kurzbezeichnungen der Regionen für enge Auswahlfelder */
  9	export const REGION_KURZ = { "de-nord": "Nord-DE", "de-ost": "Ost-DE", "de-west": "West-DE", "de-sued": "Süd-DE", at: "Österreich", ch: "Schweiz" };
