 17	/** Leistung (kWp) und Jahresertrag (kWh) eines Solarparks auf `ha` Hektar */
 18	export function parkAuf(ha, regionId) {
 19	  const region = regionById(regionId);
 20	  const kwp = (ha / FREIFLAECHE.haProMwp) * 1000;
 21	  return { kwp, kwh: kwp * region.ertrag, region };
 22	}
