 24	/**
 25	 * Pacht über die Laufzeit.
 26	 *
 27	 * eingaben:
 28	 *  ha, regionId, modell (fest|index|umsatz), proHa (€/ha·a), umsatzAnteil (0–1),
 29	 *  mindestProHa (Mindestpacht bei Umsatzmodell, €/ha·a), laufzeit (Jahre),
 30	 *  ackerProHa (heutige Ackerpacht €/ha·a), dbProHa (Deckungsbeitrag Eigenbewirtschaftung €/ha·a),
 31	 *  vorlaufJahre (Jahre bis Baubeginn mit Reservierungsprämie), reservierungProHa (€/ha·a)
 32	 *
 33	 * Rückgabe: Jahresreihen (kumuliert) für Solarpacht, Ackerpacht, Deckungsbeitrag und Kennzahlen.
 34	 */
 35	export function pachtRechnung({
 36	  ha = 10,
 37	  regionId = "de-sued",
 38	  modell = "fest",
 39	  proHa = PACHT.freiflaecheProHa.mittel,
 40	  umsatzAnteil = 0.06,
 41	  mindestProHa = PACHT.freiflaecheProHa.min,
 42	  laufzeit = PACHT.laufzeit,
 43	  ackerProHa = PACHT.ackerProHa,
 44	  dbProHa = PACHT.deckungsbeitragAcker.mittel,
 45	  vorlaufJahre = 0,
 46	  reservierungProHa = PACHT.reservierungProHa.min,
 47	} = {}) {
 48	  const { kwp, kwh, region } = parkAuf(ha, regionId);
 49	  const jahre = [];
 50	  let sumSolar = 0;
 51	  let sumAcker = 0;
 52	  let sumDb = 0;
 53	  const gesamtJahre = vorlaufJahre + laufzeit;
 54	
 55	  for (let j = 1; j <= gesamtJahre; j++) {
 56	    const betrieb = j > vorlaufJahre;
 57	    const t = j - vorlaufJahre - 1; // Betriebsjahr ab 0
 58	    let solar;
 59	    let strom = 0;
 60	    if (!betrieb) {
 61	      // Vor Baubeginn: Reservierungsprämie – die Fläche wird weiter bewirtschaftet
 62	      solar = ha * reservierungProHa;
 63	    } else if (modell === "umsatz") {
 64	      const ct = t < 20 ? ERLOESE.eegFreiflaecheCt : ERLOESE.merchantCt * Math.pow(1 + (ERLOESE.merchantSteigerung || 0), t);
 65	      strom = kwh * Math.pow(1 - FREIFLAECHE.degradation, t) * (ct / 100);
 66	      solar = Math.max(strom * umsatzAnteil, ha * mindestProHa);
 67	    } else if (modell === "index") {
 68	      solar = ha * proHa * Math.pow(1 + PACHT.indexierung, t);
 69	    } else {
 70	      solar = ha * proHa;
 71	    }
 72	    // Vergleich: Ackerpacht und Deckungsbeitrag steigen vereinfacht mit derselben Indexierung
 73	    const f = Math.pow(1 + PACHT.indexierung, j - 1);
 74	    const acker = ha * ackerProHa * f;
 75	    // Vor Baubeginn bewirtschaftet der Eigentümer weiter: Deckungsbeitrag kommt zur Prämie hinzu
 76	    const db = ha * dbProHa * f;
 77	    const solarGesamt = betrieb ? solar : solar + db;
 78	    sumSolar += solarGesamt;
 79	    sumAcker += acker;
 80	    sumDb += db;
 81	    jahre.push({ jahr: j, betrieb, solar: solarGesamt, acker, db, strom, sumSolar, sumAcker, sumDb });
 82	  }
 83	
 84	  const erstesBetriebsjahr = jahre.find((x) => x.betrieb) || jahre[0];
 85	  return {
 86	    kwp,
 87	    kwh,
 88	    region,
 89	    jahre,
 90	    ersteJahrespacht: erstesBetriebsjahr.solar,
 91	    proHaErstesJahr: erstesBetriebsjahr.solar / ha,
 92	    summeSolar: sumSolar,
 93	    summeAcker: sumAcker,
 94	    summeDb: sumDb,
 95	    faktorAcker: sumAcker > 0 ? sumSolar / sumAcker : null,
 96	    faktorDb: sumDb > 0 ? sumSolar / sumDb : null,
 97	    durchschnitt: sumSolar / gesamtJahre,
 98	    mehrGgAcker: sumSolar - sumAcker,
 99	    mehrGgDb: sumSolar - sumDb,
100	  };
101	}
102	// src/lib/rechner/agriPv.js
103	//
104	// Agri-PV-Rechner: drei Wege für Landwirte im Vergleich – reine Funktionen.
105	//  1. Verpachten      Investor baut und betreibt, Landwirt erhält Pacht und bewirtschaftet weiter
106	//  2. Eigeninvestition Landwirt investiert selbst (wir planen, bauen, vermarkten)
107	//  3. Genossenschaft  Investor/Genossenschaft baut, Landwirt erhält Pacht UND hält einen Anteil
108	//
109	// Vereinfachungen: vor Steuern, ohne Fremdfinanzierung (Projektrendite), nominal.
110	
111	import { AGRI, BAUART, ERLOESE, FREIFLAECHE, PACHT, irr, regionById } from "../invest/markt.js";
112	
113	export const SYSTEME = [
114	  { id: "vertikal", label: "Vertikal, bifazial", sub: "Kategorie II", bauart: "agriVertikal" },
115	  { id: "hoch", label: "Hoch aufgeständert", sub: "Kategorie I", bauart: "agriHoch" },
116	];
117	
118	export const kulturById = (id) => AGRI.kulturen.find((k) => k.id === id) || AGRI.kulturen[0];
119	
120	/** Kulturen, für die ein System üblich ist */
121	export const systemPasst = (kultur, system) => kultur.ertrag[system] != null;
122	
123	export function agriAnlage({ ha, system, regionId }) {
124	  const s = SYSTEME.find((x) => x.id === system) || SYSTEME[0];
125	  const b = BAUART[s.bauart];
126	  const region = regionById(regionId);
127	  const kwp = (ha / b.haProMwp) * 1000;
128	  const kwh = kwp * region.ertrag * b.faktor;
129	  const capex = kwp * AGRI.capexProKwp[s.id].mittel + (kwp / 1000) * FREIFLAECHE.netzanschlussFixProMwp + kwp * FREIFLAECHE.entwicklungProKwp.min;
130	  return { kwp, kwh, capex, region, system: s };
131	}
132	
133	/**
134	 * eingaben: { ha, system, kulturId, regionId, dbProHa?, vermarktung (eeg|ppa), anteil (0–1), laufzeit }
135	 */
136	export function agriVergleich({
137	  ha = 10,
138	  system = "vertikal",
139	  kulturId = "acker",
140	  regionId = "de-sued",
141	  dbProHa,
142	  vermarktung = "eeg",
143	  anteil = AGRI.beteiligungAnteil.standard,
144	  laufzeit = FREIFLAECHE.laufzeit,
145	} = {}) {
146	  const kultur = kulturById(kulturId);
147	  const sys = systemPasst(kultur, system) ? system : "hoch";
148	  const anlage = agriAnlage({ ha, system: sys, regionId });
149	  const land = anlage.region.land;
150	  const eeg = vermarktung === "eeg" && land === "DE";
151	  // EEG: Agri-PV bietet (Stand markt.js) im ersten Segment mit; nur hoch aufgeständerte
152	  // Anlagen erhalten den Bonus → eegBesondereCt. Vertikale Systeme: Zuschlag Freifläche.
153	  const ctFoerder = eeg ? (sys === "hoch" ? ERLOESE.eegBesondereCt : ERLOESE.eegFreiflaecheCt) : ERLOESE.ppaCt.mittel;
154	  const db = dbProHa ?? kultur.db;
155	  const ertragLw = kultur.ertrag[sys];
156	
157	  // Landwirtschaft läuft in allen drei Wegen weiter
158	  const dbJahr = ha * db * ertragLw;
159	  const dbOhneAnlage = ha * db;
160	  // GAP: in DE/AT bleibt die Fläche zu 85 % förderfähig; CH-Direktzahlungen hier nicht gerechnet
161	  const gapJahr = land === "CH" ? 0 : ha * AGRI.direktzahlungProHa * AGRI.gapFoerderfaehig;
162	  const pachtJahr0 = ha * PACHT.agriProHa.mittel;
163	
164	  // Projekt-Cashflows (Jahr 0 = Investition)
165	  const projekt = (mitPacht) => {
166	    const cf = [-anlage.capex];
167	    const jahre = [];
168	    for (let t = 0; t < laufzeit; t++) {
169	      const ct = t < 20 ? ctFoerder : ERLOESE.merchantCt * Math.pow(1 + (ERLOESE.merchantSteigerung || 0), t);
170	      const erloes = anlage.kwh * Math.pow(1 - FREIFLAECHE.degradation, t) * (ct / 100);
171	      const opex = anlage.kwp * AGRI.opexProKwp * Math.pow(1 + FREIFLAECHE.inflation, t);
172	      const pacht = mitPacht ? pachtJahr0 * Math.pow(1 + PACHT.indexierung, t) : 0;
173	      // Rückbau-Rücklage wird über die Laufzeit angespart
174	      const rueckbau = (anlage.kwp * FREIFLAECHE.rueckbauProKwp) / laufzeit;
175	      const netto = erloes - opex - pacht - rueckbau;
176	      cf.push(netto);
177	      jahre.push({ erloes, opex, pacht, netto });
178	    }
179	    return { cf, jahre };
180	  };
181	
182	  const lwReihe = (t) => (dbJahr + gapJahr) * Math.pow(1 + PACHT.indexierung, t);
183	  const summeLw = Array.from({ length: laufzeit }, (_, t) => lwReihe(t)).reduce((a, b) => a + b, 0);
184	
185	  // 1) Verpachten
186	  const pachtSumme = Array.from({ length: laufzeit }, (_, t) => pachtJahr0 * Math.pow(1 + PACHT.indexierung, t)).reduce((a, b) => a + b, 0);
187	  const pachten = {
188	    id: "pacht",
189	    invest: 0,
190	    energieJahr: pachtJahr0,
191	    energieSumme: pachtSumme,
192	    gesamtSumme: pachtSumme + summeLw,
193	    irr: null,
194	    amortisation: null,
195	    risiko: "gering",
196	  };
197	
198	  // 2) Eigeninvestition (eigene Fläche, keine Pacht)
199	  const eigen = projekt(false);
200	  const eigenSumme = eigen.cf.slice(1).reduce((a, b) => a + b, 0);
201	  const eigenInv = {
202	    id: "eigen",
203	    invest: anlage.capex,
204	    energieJahr: eigen.cf[1],
205	    energieSumme: eigenSumme - anlage.capex,
206	    gesamtSumme: eigenSumme - anlage.capex + summeLw,
207	    irr: irr(eigen.cf, -0.5, 1),
208	    amortisation: amortisation(eigen.cf),
209	    risiko: "höher",
210	    erloesJahr: eigen.jahre[0].erloes,
211	    opexJahr: eigen.jahre[0].opex,
212	  };
213	
214	  // 3) Genossenschaft / Beteiligung: Pacht + Anteil am Projekt (das Pacht zahlt)
215	  const gen = projekt(true);
216	  const genCf = gen.cf.map((x) => x * anteil);
217	  const genSumme = genCf.slice(1).reduce((a, b) => a + b, 0);
218	  const beteiligung = {
219	    id: "genossenschaft",
220	    invest: anlage.capex * anteil,
221	    energieJahr: pachtJahr0 + genCf[1],
222	    energieSumme: pachtSumme + genSumme + genCf[0],
223	    gesamtSumme: pachtSumme + genSumme + genCf[0] + summeLw,
224	    irr: irr(genCf, -0.5, 1),
225	    amortisation: amortisation(genCf),
226	    risiko: "mittel",
227	    anteil,
228	  };
229	
230	  return {
231	    anlage,
232	    kultur,
233	    system: sys,
234	    systemGewechselt: sys !== system,
235	    eeg,
236	    ctFoerder,
237	    land,
238	    landwirtschaft: { dbJahr, dbOhneAnlage, gapJahr, ertragLw, summe: summeLw },
239	    pachtJahr0,
240	    wege: [pachten, eigenInv, beteiligung],
241	    laufzeit,
242	  };
243	}
244	
245	/** Jahr, in dem der kumulierte Cashflow erstmals ≥ 0 ist (linear interpoliert) */
246	export function amortisation(cf) {
247	  let kum = cf[0];
248	  for (let t = 1; t < cf.length; t++) {
249	    const vorher = kum;
250	    kum += cf[t];
251	    if (kum >= 0 && vorher < 0) return t - 1 + -vorher / cf[t];
252	  }
253	  return null;
254	}

  1	// src/lib/rechner/grossspeicher.js
  2	//
  3	// Renditerechnung eines Batteriegroßspeichers (BESS) – Co-Location am
  4	// Solarpark oder Stand-alone am Netzknoten. Reine Funktionen ohne React:
  5	//
  6	//   node src/lib/rechner/grossspeicher.js      → Selbsttest
  7	//
  8	// Methodik (offen gelegt, vor Steuern, ohne Finanzierung):
  9	//  - Investition: Speichersystem (€/kWh) + Netzanschluss (€/kW) + Baukostenzuschuss
 10	//    (nur Stand-alone; netzdienliche Fahrweise mit Abschlag).
 11	//  - Erlöse je MW für ein 2-h-System, aufgeteilt in Arbitrage (Day-Ahead/Intraday),
 12	//    aFRR und FCR; skaliert mit der Speicherdauer. Co-Location mit Abschlag wegen
 13	//    geteilter Anschlussleistung. Arbitrage sinkt mit der Kapazität (Degradation),
 14	//    Regelleistung hängt an der Leistung und sinkt nur halb so stark. Dazu ein
 15	//    allgemeiner Erlöstrend (mehr Speicher im Markt).
 16	//  - Kosten: Betrieb in % der Investition (mit Inflation), Vermarktungsentgelt in %
 17	//    der Erlöse, ggf. Netzentgelte auf Ladestrom.
 18	//  - Kein Restwert, keine Erweiterung (Augmentation), kein Rückbau.
 19	
 20	import { SPEICHER, FREIFLAECHE, npv, irr } from "../invest/markt.js";
 21	
 22	export const STANDORTE = [
 23	  { id: "colocation", label: "Co-Location", sub: "am Solarpark" },
