  1	// src/lib/rechner/projektbewertung.js
  2	//
  3	// Orientierende Bewertung von Solarprojekten (Projektrechte) nach Phase –
  4	// reine Logik. Ausgangspunkt sind die Marktspannen je Entwicklungsstand aus
  5	// PHASEN (src/lib/invest/markt.js). Werttreiber und -minderer verschieben die
  6	// Spanne. Ergebnis ist eine Einordnung für ein erstes Gespräch, kein Gutachten:
  7	// Den tatsächlichen Preis bestimmen Due Diligence, Verhandlung und Wettbewerb.
  8	
  9	import { PHASEN, phaseById, FREIFLAECHE, ERLOESE } from "../invest/markt.js";
 10	
 11	export const LAENDER = [
 12	  { id: "DE", label: "Deutschland" },
 13	  { id: "AT", label: "Österreich" },
 14	  { id: "CH", label: "Schweiz" },
 15	];
 16	
 17	export const NETZSTATUS = [
 18	  { id: "offen", label: "Noch offen", sub: "keine Anfrage/Zusage" },
 19	  { id: "anfrage", label: "Angefragt", sub: "Netzprüfung läuft" },
 20	  { id: "zusage", label: "Zusage", sub: "Einspeisepunkt benannt" },
 21	  { id: "reserviert", label: "Reserviert", sub: "Kapazität vertraglich" },
 22	];
 23	
 24	export const VERMARKTUNG = [
 25	  { id: "keine", label: "Offen" },
 26	  { id: "eeg", label: "EEG-Zuschlag" },
 27	  { id: "ppa", label: "PPA unterschrieben" },
 28	];
 29	
 30	export const STANDARD = { mwp: 10, phase: "satzung", netz: "zusage", netzKm: 1.5, vermarktung: "keine", land: "DE" };
 31	
 32	const idx = (id) => PHASEN.findIndex((p) => p.id === id);
 33	
 34	/**
 35	 * @returns {{ phase, preisKwp:{min,mittel,max}, gesamt:{min,mittel,max}, risiko, risikoStufe, treiber:[], minderer:[], hinweise:[], monateBisRtb }}
 36	 */
 37	export function bewerteProjekt(eingabe = {}) {
 38	  const e = { ...STANDARD, ...eingabe };
 39	  const phase = phaseById(e.phase);
 40	  const pi = idx(phase.id);
 41	  const bestand = phase.id === "cod";
 42	  const kwp = e.mwp * 1000;
 43	
 44	  let { min, max } = phase.preisProKwp;
 45	  const treiber = [];
 46	  const minderer = [];
 47	  const hinweise = [];
 48	  let risikoStufe = pi <= 0 ? 5 : pi === 1 ? 4 : pi === 2 ? 3 : pi === 3 ? 2 : 1; // 5 sehr hoch … 0 sehr gering
 49	  if (bestand) risikoStufe = 0;
 50	
 51	  // Faktoren multiplizieren die Spanne, Abzüge (€/kWp) verschieben sie
 52	  let faktor = 1;
 53	  let abzug = 0;
 54	
 55	  /* --- Netzanschluss ------------------------------------------------ */
 56	  if (!bestand) {
 57	    const netzPhase = idx("netz");
 58	    if (e.netz === "reserviert") {
 59	      faktor *= 1.1;
 60	      treiber.push("Netzkapazität vertraglich reserviert – der größte Engpass im Markt ist gelöst.");
 61	      if (pi < netzPhase) risikoStufe -= 1;
 62	    } else if (e.netz === "zusage") {
 63	      if (pi < netzPhase) {
 64	        faktor *= 1.25;
 65	        risikoStufe -= 1;
 66	        treiber.push("Netzzusage liegt schon vor der üblichen Phase vor – deutlicher Wertsprung.");
 67	      } else {
 68	        treiber.push("Netzzusage mit benanntem Einspeisepunkt.");
 69	      }
 70	    } else if (e.netz === "anfrage") {
 71	      if (pi >= netzPhase) {
 72	        faktor *= 0.7;
 73	        risikoStufe += 1;
 74	        minderer.push("Für diese Phase fehlt die Netzzusage noch – Käufer preisen Verzögerung und Kosten ein.");
 75	      } else {
 76	        hinweise.push("Netzanfrage gestellt: Mit der Zusage steigt der Wert typischerweise spürbar.");
 77	      }
 78	    } else {
 79	      if (pi >= netzPhase) {
 80	        faktor *= 0.5;
 81	        risikoStufe += 2;
 82	        minderer.push("Ohne Netzanfrage ist der Anschluss das zentrale Risiko – viele Käufer steigen erst mit Zusage ein.");
 83	      } else {
 84	        minderer.push("Netzanschluss noch nicht angefragt – in vielen Regionen der Engpass Nummer eins.");
 85	      }
 86	    }
 87	
 88	    // Kabeltrasse: Mehrkosten gegenüber ~1 km Standard mindern den Wert direkt
 89	    const mehrKm = Math.max(0, e.netzKm - 1);
 90	    if (mehrKm > 0) {
 91	      abzug += (mehrKm * 1000 * FREIFLAECHE.kabelProMeter) / kwp;
 92	      const eurKwp = Math.round((mehrKm * 1000 * FREIFLAECHE.kabelProMeter) / kwp);
 93	      if (eurKwp >= 5) minderer.push(`Kabeltrasse ${String(e.netzKm).replace(".", ",")} km: rund ${eurKwp} €/kWp Mehrkosten für den Käufer.`);
 94	    } else {
 95	      treiber.push("Einspeisepunkt in unmittelbarer Nähe – geringe Anschlusskosten.");
 96	    }
 97	    if (e.netzKm > 8) {
 98	      risikoStufe += 1;
 99	      minderer.push("Lange Trasse bedeutet zusätzliche Wegerechte und Genehmigungen.");
100	    }
101	  }
102	
103	  /* --- Größe ----------------------------------------------------------- */
104	  if (e.mwp < 3) {
105	    faktor *= 0.75;
106	    minderer.push("Unter 3 MWp: Fixkosten für Netz, Gutachten und Due Diligence verteilen sich auf wenig Leistung – kleinerer Käuferkreis.");
107	  } else if (e.mwp < 8) {
108	    faktor *= 0.9;
109	    minderer.push("Unter 8 MWp: für institutionelle Käufer oft unter der Mindestgröße.");
110	  } else if (e.mwp >= 50) {
111	    faktor *= 1.12;
112	    treiber.push("Ab 50 MWp: interessant für institutionelle Investoren und Portfoliokäufer.");
113	  } else if (e.mwp >= 20) {
114	    faktor *= 1.06;
115	    treiber.push("Ab 20 MWp: breiter Käuferkreis, Skaleneffekte bei Bau und Betrieb.");
116	  }
117	
118	  /* --- Vermarktung ---------------------------------------------------- */
119	  if (e.vermarktung === "eeg") {
120	    if (e.land !== "DE") {
121	      hinweise.push("EEG-Zuschlag gibt es nur in Deutschland – in Österreich entspricht dem die EAG-Marktprämie aus der Ausschreibung.");
122	    }
123	    if (pi >= idx("satzung") || bestand) {
124	      faktor *= 1.12;
125	      risikoStufe -= 1;
126	      treiber.push("Zuschlag gesichert: 20 Jahre Marktprämie als Erlösboden – bankfähig.");
127	    } else {
128	      hinweise.push("Ein Zuschlag setzt in der Regel Baurecht voraus – bitte Phase prüfen.");
129	    }
130	  } else if (e.vermarktung === "ppa") {
131	    faktor *= 1.1;
132	    risikoStufe -= 1;
133	    treiber.push("Unterschriebener PPA: planbare Erlöse, erleichtert die Finanzierung.");
134	  } else if (pi >= idx("satzung")) {
135	    hinweise.push(`Noch ohne Vermarktung: Zuletzt lagen EEG-Zuschläge um ${String(ERLOESE.eegFreiflaecheCt).replace(".", ",")} ct/kWh, PPA-Preise grob zwischen ${String(ERLOESE.ppaCt.min).replace(".", ",")} und ${String(ERLOESE.ppaCt.max).replace(".", ",")} ct/kWh.`);
136	  }
137	
138	  /* --- Land ------------------------------------------------------------ */
139	  if (e.land === "AT") {
140	    hinweise.push("Österreich: Flächenwidmung (z. B. Grünland-Photovoltaik) und Förderung nach EAG (Marktprämie bzw. Investitionszuschuss) prägen den Wert; ab bestimmten Größen ist eine UVP-Prüfung nötig.");
141	  } else if (e.land === "CH") {
142	    faktor *= 0.9;
143	    hinweise.push("Schweiz: kleiner Markt für Freiflächenprojekte, Bewilligung meist über Nutzungsplanung bzw. Solarexpress (alpine Anlagen) – Vergleichswerte sind rar, die Spanne ist unsicherer.");
144	  }
145	
146	  if (!bestand && pi < idx("aufstellung")) {
147	    hinweise.push("Frühe Phase: Viele Käufer zahlen gestaffelt – ein Teil bei Signing, der Rest bei Meilensteinen (Satzungsbeschluss, RTB).");
148	  }
149	  if (bestand) {
150	    hinweise.push("Bestandsanlage: Maßgeblich sind Erlöse, Restlaufzeit von Förderung/PPA, Pachtvertrag, technischer Zustand und Ertragshistorie – der Wert folgt dem Barwert der Cashflows.");
151	  }
152	
153	  const clamp = (v) => Math.max(0, v);
154	  const preisKwp = {
155	    min: clamp(min * faktor - abzug),
156	    max: clamp(max * faktor - abzug),
157	  };
158	  preisKwp.mittel = (preisKwp.min + preisKwp.max) / 2;
159	  const gesamt = { min: preisKwp.min * kwp, mittel: preisKwp.mittel * kwp, max: preisKwp.max * kwp };
160	
161	  // Vor Inbetriebnahme bleibt immer ein Rest-Risiko (Bau, Netz, Vermarktung)
162	  risikoStufe = Math.max(bestand ? 0 : 1, Math.min(5, risikoStufe));
163	  const RISIKO = ["sehr gering", "gering", "mittel", "mittel–hoch", "hoch", "sehr hoch"];
164	
165	  return {
166	    eingabe: e,
167	    phase,
168	    phaseIndex: pi,
169	    kwp,
170	    faktor,
171	    abzugKwp: abzug,
172	    preisKwp,
173	    gesamt,
174	    risiko: RISIKO[risikoStufe],
175	    risikoStufe,
176	    treiber,
177	    minderer,
178	    hinweise,
179	    monateBisRtb: phase.monateBisRtb,
180	    kaufpreisNull: preisKwp.max <= 0,
181	  };
182	}
