188	export function selbsttest() {
189	  const fehler = [];
190	  const pruefe = (ok, text) => {
191	    if (!ok) fehler.push(text);
192	  };
193	  const neutral = bewerteProjekt({ mwp: 10, phase: "rtb", netz: "zusage", netzKm: 1, vermarktung: "keine", land: "DE" });
194	  pruefe(neutral.preisKwp.min === 60 && neutral.preisKwp.max === 130, "RTB neutral = PHASEN-Spanne");
195	  pruefe(neutral.gesamt.min === 600000, "10 MWp × 60 €/kWp = 600.000 €");
196	
197	  for (let i = 1; i < PHASEN.length; i++) {
198	    const a = bewerteProjekt({ phase: PHASEN[i - 1].id, netz: "zusage", netzKm: 1 });
199	    const b = bewerteProjekt({ phase: PHASEN[i].id, netz: "zusage", netzKm: 1 });
200	    pruefe(b.preisKwp.mittel >= a.preisKwp.mittel * 0.9, `Wert steigt tendenziell mit der Phase (${PHASEN[i].id})`);
201	  }
202	  const ohneNetz = bewerteProjekt({ phase: "rtb", netz: "offen" });
203	  pruefe(ohneNetz.preisKwp.mittel < neutral.preisKwp.mittel, "fehlende Netzanfrage mindert den Wert");
204	  const weit = bewerteProjekt({ phase: "rtb", netz: "zusage", netzKm: 6 });
205	  pruefe(weit.preisKwp.mittel < neutral.preisKwp.mittel && weit.minderer.length > 0, "lange Trasse mindert den Wert");
206	  const klein = bewerteProjekt({ mwp: 2, phase: "rtb", netz: "zusage", netzKm: 1 });
207	  pruefe(klein.preisKwp.mittel < neutral.preisKwp.mittel, "kleine Projekte je kWp günstiger");
208	  const eeg = bewerteProjekt({ phase: "rtb", netz: "zusage", netzKm: 1, vermarktung: "eeg" });
209	  pruefe(eeg.preisKwp.mittel > neutral.preisKwp.mittel && eeg.risikoStufe <= neutral.risikoStufe, "Zuschlag erhöht Wert, senkt Risiko");
210	  const extrem = bewerteProjekt({ mwp: 1, phase: "flaeche", netz: "offen", netzKm: 20 });
211	  pruefe(extrem.preisKwp.min >= 0 && extrem.preisKwp.max >= 0, "nie negative Preise");
212	  pruefe(bewerteProjekt({ phase: "cod" }).preisKwp.min > 300, "Bestand bewertet als Anlage");
213	  return fehler;
214	}
