  2	//
  3	// Was ein Solarpark der Standortgemeinde bringt – reine Logik (Deutschland).
  4	// Quellen der Einnahmen:
  5	//  1. § 6 EEG: freiwillige Zahlung des Betreibers bis 0,2 ct/kWh
  6	//  2. Gewerbesteuer: 90 % des Messbetrags an die Standortgemeinde
  7	//     (§ 29 Abs. 1 Nr. 2 GewStG), 100 %, wenn der Betreiber dort seinen Sitz hat
  8	//  3. Pacht, wenn Flächen der Gemeinde genutzt werden
  9	//
 10	// Die Gewerbesteuer wird vereinfacht aus der Solarpark-Rechnung abgeleitet:
 11	// Ergebnis = EBITDA − lineare AfA − Zinsen, Hinzurechnung von 25 % der Zinsen
 12	// über 200.000 €, Verlustvortrag ohne Mindestbesteuerung. Typisch ist, dass in
 13	// den ersten Jahren durch Abschreibung und Zinsen kaum Gewerbesteuer anfällt.
 14	
 15	import { KOMMUNE, BAUART, PACHT, ERLOESE, FREIFLAECHE } from "../invest/markt.js";
 16	import { rechneSolarpark } from "./solarpark.js";
 17	
 18	export const STANDARD = {
 19	  mwp: 20,
 20	  regionId: "de-sued",
 21	  bauart: "sued",
 22	  hebesatz: KOMMUNE.hebesatz,
 23	  paragraph6: true,
 24	  gemeindeflaeche: false,
 25	  anteilGemeinde: 1,
 26	  pachtHa: PACHT.freiflaecheProHa.mittel,
 27	  sitzInGemeinde: false,
 28	  /** Erlös des Parks in ct/kWh (EEG-Zuschlag bzw. PPA) – bestimmt den Gewinn und damit die Gewerbesteuer */
 29	  preisCt: ERLOESE.eegFreiflaecheCt,
 30	};
 31	
 32	export function rechneKommune(eingabe = {}) {
 33	  const e = { ...STANDARD, ...eingabe };
 34	  const N = KOMMUNE.betrachtungJahre;
 35	  const L = FREIFLAECHE.laufzeit; // gesamte Laufzeit – nach Ende der AfA steigt die Gewerbesteuer
 36	  const park = rechneSolarpark({ mwp: e.mwp, regionId: e.regionId, bauart: e.bauart, pachtHa: e.pachtHa, preisCt: e.preisCt, modell: "eeg", laufzeit: L });
 37	  const flaecheHa = e.mwp * (BAUART[e.bauart] || BAUART.sued).haProMwp;
 38	  const afa = park.investition.summe / KOMMUNE.afaJahre;
 39	  const anteilGewSt = e.sitzInGemeinde ? 1 : KOMMUNE.gewerbesteuerStandort;
 40	
 41	  let verlustvortrag = 0;
 42	  const jahre = [];
 43	  for (let t = 1; t <= L; t++) {
 44	    const j = park.jahre[t - 1];
 45	    const p6 = e.paragraph6 ? (j.erzeugung * KOMMUNE.beteiligungCt) / 100 : 0;
 46	    // § 6-Zahlung ist beim Betreiber Betriebsausgabe (Erstattung durch den Netzbetreiber bei EEG-Anlagen – vereinfacht neutral)
 47	    const ergebnis = j.ebitda - (t <= KOMMUNE.afaJahre ? afa : 0) - j.zinsen;
 48	    const hinzurechnung = Math.max(0, j.zinsen - KOMMUNE.hinzurechnungFreibetrag) * KOMMUNE.hinzurechnungZinsen;
 49	    let ertrag = ergebnis + hinzurechnung;
 50	    if (ertrag < 0) {
 51	      verlustvortrag += -ertrag;
 52	      ertrag = 0;
 53	    } else if (verlustvortrag > 0) {
 54	      const verrechnet = Math.min(verlustvortrag, ertrag);
 55	      verlustvortrag -= verrechnet;
 56	      ertrag -= verrechnet;
 57	    }
 58	    const gewSt = ertrag * KOMMUNE.messzahl * e.hebesatz * anteilGewSt;
 59	    const pacht = e.gemeindeflaeche ? flaecheHa * e.anteilGemeinde * e.pachtHa * Math.pow(1 + PACHT.indexierung, t - 1) : 0;
 60	    jahre.push({ jahr: t, p6, gewSt, pacht, summe: p6 + gewSt + pacht, erzeugung: j.erzeugung });
 61	  }
 62	  const summeBis = (k, bis) => jahre.slice(0, bis).reduce((s, j) => s + j[k], 0);
 63	  const topf = (bis) => {
 64	    const g = { p6: summeBis("p6", bis), gewSt: summeBis("gewSt", bis), pacht: summeBis("pacht", bis) };
 65	    g.summe = g.p6 + g.gewSt + g.pacht;
 66	    return g;
 67	  };
 68	  const gesamt = topf(N);
 69	  const gesamtLaufzeit = topf(L);
 70	  const ersteGewSt = jahre.find((j) => j.gewSt > 0)?.jahr ?? null;
 71	  const spaet = jahre.slice(KOMMUNE.afaJahre);
 72	  const gewStNachAfa = spaet.length ? spaet.reduce((s, j) => s + j.gewSt, 0) / spaet.length : 0;
 73	
 74	  return {
 75	    eingabe: e,
 76	    jahre,
 77	    gesamt,
 78	    gesamtLaufzeit,
 79	    gewStNachAfa,
 80	    proJahr: gesamt.summe / N,
 81	    jahre1: jahre[0],
 82	    ersteGewSt,
 83	    flaecheHa,
 84	    ertragJahr1: park.ertragJahr1,
 85	    investition: park.investition.summe,
 86	    N,
 87	    L,
 88	  };
 89	}
