176	    land: landId,
177	    regionId: (regionen.find((r) => r.id === "de-sued") || regionen[0]).id,
178	    rabattId: l.rabatte[0].id,
179	    kwp: 250,
180	    teilnehmer: 60,
181	    verbrauchJe: 3500,
182	    mix: "gemischt",
183	    speicher: false,
184	    energiepreis: l.energiepreis,
185	    netzAp: l.netzAp,
186	    gemeinschaftCt: l.gemeinschaftCt,
187	    ueberschussCt: l.ueberschussCt,
188	    verwaltung: l.verwaltung,
189	  };
190	}
191	
192	export function geteilteMenge(erzeugung, verbrauch, a) {
193	  if (verbrauch <= 0 || erzeugung <= 0) return 0;
194	  const R = erzeugung / verbrauch;
195	  return verbrauch * a * (1 - Math.exp(-R / a));
196	}
197	
198	export function rechneEnergySharing(eingabe = {}) {
199	  const e = { ...standardFuer(eingabe.land || "de"), ...eingabe };
200	  const l = land(e.land);
201	  const region = REGIONEN.find((r) => r.id === e.regionId) || regionenFuer(e.land)[0];
202	  const rabatt = l.rabatte.find((r) => r.id === e.rabattId) || l.rabatte[0];
203	  const mix = MIXE.find((m) => m.id === e.mix) || MIXE[1];
204	  const a = Math.min(0.9, mix.a + (e.speicher ? SPEICHER_PLUS : 0));
205	
206	  const erzeugung = e.kwp * region.ertrag;
207	  const verbrauch = e.teilnehmer * e.verbrauchJe;
208	  const geteilt = geteilteMenge(erzeugung, verbrauch, a);
209	  const ueberschuss = Math.max(0, erzeugung - geteilt);
210	
211	  // Vorteil je geteilter kWh (ct bzw. Rp.)
212	  const teile = [
213	    { id: "energie", label: "Günstigerer Energiepreis", ct: e.energiepreis - e.gemeinschaftCt },
214	    { id: "netz", label: "Abschlag Netzentgelt", ct: e.netzAp * rabatt.anteil },
215	    { id: "abgaben", label: "Entfallende Abgaben", ct: l.abgabenCt },
216	  ];
217	  const vorteilCt = teile.reduce((s, t) => s + t.ct, 0);
218	  const vorteilBrutto = (geteilt * vorteilCt) / 100;
219	  const verwaltungGesamt = e.teilnehmer * e.verwaltung;
220	  const vorteilNetto = vorteilBrutto - verwaltungGesamt;
221	
222	  const erloesGeteilt = (geteilt * e.gemeinschaftCt) / 100;
223	  const erloesUeberschuss = (ueberschuss * e.ueberschussCt) / 100;
224	  const erloesErzeuger = erloesGeteilt + erloesUeberschuss;
225	  const referenzErzeuger = (erzeugung * e.ueberschussCt) / 100;
226	
227	  return {
228	    eingabe: e,
229	    land: l,
230	    region,
231	    rabatt,
232	    a,
233	    erzeugung,
234	    verbrauch,
235	    geteilt,
236	    ueberschuss,
237	    deckung: verbrauch > 0 ? geteilt / verbrauch : 0,
238	    nutzung: erzeugung > 0 ? geteilt / erzeugung : 0,
239	    teile,
240	    vorteilCt,
241	    vorteilBrutto,
242	    verwaltungGesamt,
243	    vorteilNetto,
244	    jeTeilnehmer: e.teilnehmer > 0 ? vorteilNetto / e.teilnehmer : 0,
245	    geteiltJeTeilnehmer: e.teilnehmer > 0 ? geteilt / e.teilnehmer : 0,
246	    erloesErzeuger,
247	    erloesGeteilt,
248	    erloesUeberschuss,
249	    mehrerloesErzeuger: erloesErzeuger - referenzErzeuger,
250	    referenzErzeuger,
251	    lohntSich: vorteilNetto > 0,
252	  };
253	}
