259	export function selbsttest() {
260	  const fehler = [];
261	  const pruefe = (ok, t) => ok || fehler.push(t);
262	
263	  pruefe(Math.abs(geteilteMenge(1000, 1e6, 0.4) - 1000) < 20, "kleine Anlage: fast alles wird geteilt");
264	  pruefe(geteilteMenge(1e7, 1e5, 0.4) <= 0.4 * 1e5 + 1e-6, "große Anlage: Deckel bei a × Verbrauch");
265	
266	  const de = rechneEnergySharing({ land: "de" });
267	  const at = rechneEnergySharing({ land: "at", rabattId: "lokal" });
268	  const atBeg = rechneEnergySharing({ land: "at", rabattId: "beg" });
269	  const ch = rechneEnergySharing({ land: "ch", rabattId: "leg40" });
270	  pruefe(de.teile.find((t) => t.id === "netz").ct === 0, "DE: kein Netzentgeltabschlag");
271	  pruefe(Math.abs(at.teile.find((t) => t.id === "netz").ct - 7 * 0.57) < 1e-9, "AT lokal: 57 % von 7 ct");
272	  pruefe(at.vorteilCt > atBeg.vorteilCt, "AT lokal günstiger als BEG");
273	  pruefe(Math.abs(ch.teile.find((t) => t.id === "netz").ct - 4) < 1e-9, "CH LEG: 40 % von 10 Rp.");
274	  pruefe(de.geteilt <= de.erzeugung && de.geteilt <= de.verbrauch, "geteilt ≤ Erzeugung und ≤ Verbrauch");
275	  const sp = rechneEnergySharing({ land: "de", speicher: true, kwp: 800 });
276	  const ohneSp = rechneEnergySharing({ land: "de", speicher: false, kwp: 800 });
277	  pruefe(sp.geteilt > ohneSp.geteilt, "Speicher erhöht den geteilten Anteil");
278	  pruefe(Math.abs(de.erloesErzeuger - (de.erloesGeteilt + de.erloesUeberschuss)) < 1e-9, "Erzeugererlös konsistent");
279	  pruefe(de.mehrerloesErzeuger > 0, "Gemeinschaftspreis über Überschussvergütung → Mehrerlös für Erzeuger");
280	  return { fehler, beispiel: { de, at, ch } };
281	}
282	
283	if (typeof process !== "undefined" && process.argv?.[1] && /energySharing\.js$/.test(process.argv[1].replace(/\\/g, "/"))) {
284	  const { fehler, beispiel } = selbsttest();
285	  for (const [k, r] of Object.entries(beispiel))
286	    console.log(`${k.toUpperCase()}: geteilt ${Math.round(r.geteilt / 1000)} MWh (${(r.nutzung * 100).toFixed(0)} % der Erzeugung), Vorteil ${r.vorteilCt.toFixed(2)} ct/kWh, je Teilnehmer ${Math.round(r.jeTeilnehmer)} ${r.land.waehrung}/a`);
287	  if (fehler.length) {
288	    console.error("FEHLER:\n- " + fehler.join("\n- "));
289	    process.exit(1);
290	  }
291	  console.log("Selbsttest energySharing.js: alle Prüfungen bestanden.");
292	}

  1	// src/lib/rechner/reststrom.js
  2	//
  3	// Reststrom-Rechner: Was kann der Pool (Bündelung, Solar-PPA, Flexibilität)
  4	// beim Strom sparen, den ein Unternehmen trotz eigener PV noch aus dem Netz
  5	// bezieht? Reine Funktionen ohne React – im Browser UND in Node testbar:
  6	//
  7	//   node src/lib/rechner/reststrom.js      → Selbsttest
  8	//
  9	// Alle Marktwerte kommen aus src/lib/invest/markt.js (STROM, REGIONEN).
 10	// Ergebnis ist eine Spanne zur Orientierung, kein Angebot.
 11	
 12	import { STROM, REGIONEN } from "../invest/markt.js";
 13	
 14	/**
 15	 * Lastprofile. `tag` = Anteil des Verbrauchs in den Solarstunden (ca. 8–17 Uhr),
 16	 * `ppa`/`flex` = Faktoren auf die Hebel-Spannen aus STROM.poolHebel,
 17	 * `eigenverbrauch` = typische Eigenverbrauchsquote einer eigenen PV-Anlage.
 18	 * Eigene, vorsichtige Einschätzung auf Basis typischer Gewerbe-Lastgänge.
 19	 */
 20	export const LASTPROFILE = [
 21	  { id: "einschicht", label: "Einschicht", sub: "ca. 6–16 Uhr", tag: 0.62, ppa: 1.0, flex: 0.8, eigenverbrauch: 0.7 },
 22	  { id: "zweischicht", label: "Zweischicht", sub: "ca. 6–22 Uhr", tag: 0.5, ppa: 0.85, flex: 1.0, eigenverbrauch: 0.8 },
 23	  { id: "dreischicht", label: "Dreischicht", sub: "rund um die Uhr", tag: 0.38, ppa: 0.65, flex: 0.75, eigenverbrauch: 0.9 },
 24	  { id: "handel", label: "Handel & Büro", sub: "Laden, Kühlung, Klima", tag: 0.55, ppa: 0.9, flex: 0.9, eigenverbrauch: 0.75 },
 25	];
 26	
 27	export const profilById = (id) => LASTPROFILE.find((p) => p.id === id) || LASTPROFILE[0];
 28	
 29	/** Mittlerer spezifischer Ertrag einer Gewerbe-PV (Dach, nicht optimal ausgerichtet) – Mittel der DE-Regionen × 0,9 */
 30	const DE_REGIONEN = REGIONEN.filter((r) => r.land === "DE");
 31	export const PV_ERTRAG_KWH_PRO_KWP = Math.round((DE_REGIONEN.reduce((s, r) => s + r.ertrag, 0) / DE_REGIONEN.length) * 0.9);
 32	
 33	/** Ab dieser Menge ist ein Pool-Beitritt in der Regel sinnvoll (MWh/Jahr) – vorsichtige Orientierung */
 34	export const SINNVOLL_AB_MWH = 100;
 35	
 36	/** Die Beschaffung lässt sich nicht beliebig drücken: max. Anteil der Beschaffungskomponente, der eingespart werden kann */
 37	const MAX_ANTEIL_BESCHAFFUNG = 0.35;
 38	
 39	const fixeBestandteile = () => STROM.bestandteile.filter((b) => !b.beeinflussbar);
 40	const stromsteuerRegel = () => STROM.bestandteile.find((b) => b.id === "stromsteuer")?.ct ?? 0;
 41	
 42	/**
 43	 * @param {object} e
 44	 * @param {number} e.verbrauchMwh     Jahresverbrauch aus dem Netz heute (MWh)
 45	 * @param {number} e.preisCt          aktueller Arbeitspreis gesamt, netto (ct/kWh)
 46	 * @param {string} e.profil           id aus LASTPROFILE
 47	 * @param {number} e.pvKwp            eigene PV-Leistung (0 = keine)
 48	 * @param {boolean} e.pvBestand       true: PV läuft schon (Verbrauch oben ist bereits Reststrom)
 49	 * @param {boolean} e.produzierend    produzierendes Gewerbe / Land- und Forstwirtschaft
 50	 */
 51	export function berechneReststrom({ verbrauchMwh = 500, preisCt = 20, profil = "einschicht", pvKwp = 0, pvBestand = false, produzierend = false } = {}) {
 52	  const p = profilById(profil);
 53	  const verbrauchKwh = Math.max(0, verbrauchMwh) * 1000;
 54	
 55	  // 1) Eigene PV: Eigenverbrauch deckt einen Teil der Tagesstunden
 56	  const pvErtrag = Math.max(0, pvKwp) * PV_ERTRAG_KWH_PRO_KWP;
 57	  const tagesLast = verbrauchKwh * p.tag;
 58	  // Geplante PV: Eigenverbrauch höchstens 90 % der Tageslast
 59	  const eigenverbrauch = pvBestand ? 0 : Math.min(pvErtrag * p.eigenverbrauch, tagesLast * 0.9);
 60	  const reststromKwh = Math.max(0, verbrauchKwh - eigenverbrauch);
 61	  // Wie stark sind die Tagesstunden schon durch eigene PV gedeckt? (bestimmt den PPA-Spielraum)
 62	  const pvDeckungTag = tagesLast > 0 ? Math.min(1, (pvErtrag * p.eigenverbrauch) / tagesLast) : 0;
 63	
 64	  // 2) Preiszerlegung heute
 65	  const fix = fixeBestandteile().map((b) => ({ ...b }));
 66	  const fixSumme = fix.reduce((s, b) => s + b.ct, 0);
 67	  const beschaffungVorher = Math.max(0, preisCt - fixSumme);
 68	  const preisUnplausibel = preisCt < fixSumme + 3;
 69	
 70	  // 3) Hebel des Pools in ct/kWh Reststrom
 71	  const faktor = {
 72	    buendelung: 1,
 73	    ppa: p.ppa * Math.max(0.25, 1 - pvDeckungTag),
 74	    flex: p.flex * (pvKwp > 0 ? 1.1 : 1),
 75	  };
 76	  let hebel = STROM.poolHebel.map((h) => {
 77	    const f = faktor[h.id] ?? 1;
 78	    return { id: h.id, label: h.label, ctMin: h.ct.min * f, ctMax: h.ct.max * f };
 79	  });
 80	
 81	  // Deckel: nie mehr als MAX_ANTEIL_BESCHAFFUNG der heutigen Beschaffungskomponente
 82	  const deckel = beschaffungVorher * MAX_ANTEIL_BESCHAFFUNG;
 83	  const summeMax = hebel.reduce((s, h) => s + h.ctMax, 0);
 84	  if (summeMax > deckel) {
 85	    // proportional kürzen – Verhältnis der Hebel bleibt erhalten
 86	    const k = summeMax > 0 ? deckel / summeMax : 0;
 87	    hebel = hebel.map((h) => ({ ...h, ctMin: h.ctMin * k, ctMax: h.ctMax * k }));
 88	  }
 89	  hebel = hebel.map((h) => ({ ...h, eurMin: (h.ctMin / 100) * reststromKwh, eurMax: (h.ctMax / 100) * reststromKwh }));
 90	
 91	  const gesamt = {
 92	    ctMin: hebel.reduce((s, h) => s + h.ctMin, 0),
 93	    ctMax: hebel.reduce((s, h) => s + h.ctMax, 0),
 94	  };
 95	  gesamt.ctMitte = (gesamt.ctMin + gesamt.ctMax) / 2;
 96	  gesamt.eurMin = (gesamt.ctMin / 100) * reststromKwh;
 97	  gesamt.eurMax = (gesamt.ctMax / 100) * reststromKwh;
 98	  gesamt.eurMitte = (gesamt.eurMin + gesamt.eurMax) / 2;
 99	
100	  const kostenVorher = (preisCt / 100) * reststromKwh;
101	  gesamt.anteilMin = kostenVorher > 0 ? gesamt.eurMin / kostenVorher : 0;
102	  gesamt.anteilMax = kostenVorher > 0 ? gesamt.eurMax / kostenVorher : 0;
103	
104	  // 4) Preiszerlegung vorher/nachher (nachher mit Mitte der Spanne)
105	  const vorher = [{ id: "beschaffung", label: "Beschaffung & Vertrieb", ct: beschaffungVorher, beeinflussbar: true }, ...fix];
106	  const nachher = [{ id: "beschaffung", label: "Beschaffung & Vertrieb (Pool)", ct: Math.max(0, beschaffungVorher - gesamt.ctMitte), beeinflussbar: true }, ...fix];
107	
108	  // 5) Stromsteuer-Entlastung (separat, keine Pool-Leistung – Antrag beim Hauptzollamt)
109	  const steuerDiff = stromsteuerRegel() - STROM.stromsteuerProduzierend;
110	  const stromsteuer = produzierend
111	    ? { ctJeKwh: steuerDiff, eur: (steuerDiff / 100) * reststromKwh }
112	    : null;
113	
114	  return {
115	    profil: p,
116	    verbrauchKwh,
117	    pvErtrag,
118	    eigenverbrauch,
119	    reststromKwh,
120	    pvDeckungTag,
121	    fixSumme,
122	    beschaffungVorher,
123	    preisUnplausibel,
124	    kostenVorher,
125	    hebel,
126	    gesamt,
127	    vorher,
128	    nachher,
129	    stromsteuer,
130	    klein: verbrauchMwh < SINNVOLL_AB_MWH,
131	  };
132	}
133	
