138	export function selbsttest() {
139	  const fehler = [];
140	  const pruefe = (bed, text) => { if (!bed) fehler.push(text); };
141	
142	  const basis = berechneReststrom({ verbrauchMwh: 1000, preisCt: 20, profil: "einschicht" });
143	  pruefe(basis.reststromKwh === 1_000_000, "ohne PV ist Reststrom = Verbrauch");
144	  pruefe(basis.hebel.length === STROM.poolHebel.length, "je Hebel ein Ergebnis");
145	  pruefe(basis.gesamt.eurMin > 0 && basis.gesamt.eurMax > basis.gesamt.eurMin, "Spanne positiv und geordnet");
146	  pruefe(basis.gesamt.ctMax <= basis.beschaffungVorher * 0.35 + 1e-9, "Deckel auf Beschaffung eingehalten");
147	  pruefe(Math.abs(basis.vorher.reduce((s, b) => s + b.ct, 0) - 20) < 1e-9, "Zerlegung vorher summiert auf Eingabepreis");
148	  pruefe(basis.nachher.reduce((s, b) => s + b.ct, 0) < 20, "nachher günstiger als vorher");
149	  pruefe(basis.stromsteuer === null, "ohne produzierendes Gewerbe keine Stromsteuer-Entlastung");
150	
151	  const pv = berechneReststrom({ verbrauchMwh: 1000, preisCt: 20, profil: "einschicht", pvKwp: 500 });
152	  pruefe(pv.reststromKwh < basis.reststromKwh, "geplante PV senkt den Reststrom");
153	  const ppaOhne = basis.hebel.find((h) => h.id === "ppa").ctMax;
154	  const ppaMit = pv.hebel.find((h) => h.id === "ppa").ctMax;
155	  pruefe(ppaMit < ppaOhne, "eigene PV verkleinert den PPA-Hebel");
156	
157	  const best = berechneReststrom({ verbrauchMwh: 1000, preisCt: 20, pvKwp: 500, pvBestand: true });
158	  pruefe(best.reststromKwh === 1_000_000, "bestehende PV: Verbrauch ist bereits Reststrom");
159	
160	  const drei = berechneReststrom({ verbrauchMwh: 1000, preisCt: 20, profil: "dreischicht" });
161	  pruefe(drei.hebel.find((h) => h.id === "ppa").ctMax < ppaOhne, "Dreischicht: weniger PPA-Potenzial als Einschicht");
162	
163	  const prod = berechneReststrom({ verbrauchMwh: 1000, preisCt: 20, produzierend: true });
164	  pruefe(prod.stromsteuer && Math.abs(prod.stromsteuer.eur - 20000) < 1, "Stromsteuer-Entlastung 2,0 ct × 1 GWh = 20.000 €");
165	
166	  const billig = berechneReststrom({ verbrauchMwh: 1000, preisCt: 9 });
167	  pruefe(billig.beschaffungVorher === 0 && billig.gesamt.eurMax === 0, "unplausibel niedriger Preis → keine Ersparnis");
168	  pruefe(billig.preisUnplausibel, "unplausibel niedriger Preis wird markiert");
169	
170	  pruefe(berechneReststrom({ verbrauchMwh: 50 }).klein, "unter 100 MWh als klein markiert");
171	  for (const h of basis.hebel) pruefe(h.ctMin <= h.ctMax, `Hebel ${h.id}: min ≤ max`);
172	
173	  return fehler;
174	}
175	
176	if (typeof process !== "undefined" && process.argv?.[1] && /reststrom\.js$/.test(process.argv[1].replace(/\\/g, "/"))) {
177	  const f = selbsttest();
178	  const b = berechneReststrom({ verbrauchMwh: 1000, preisCt: 20 });
179	  console.log("Beispiel 1.000 MWh, 20 ct:", Math.round(b.gesamt.eurMin), "–", Math.round(b.gesamt.eurMax), "€/Jahr");
180	  if (f.length) {
181	    console.error("FEHLER:\n- " + f.join("\n- "));
182	    process.exit(1);
