184	  console.log("Selbsttest reststrom.js: alle Prüfungen bestanden.");
185	}

  1	// src/lib/rechner/netzanschluss.js
  2	//
  3	// Netzanschluss-Check für Solarparks: grobe Kosten, Zeitrahmen, Risiken und
  4	// Tipps je nach Größe, Entfernung, Spannungsebene, Netzkapazität, Überbauung
  5	// und Speicher. Reine Funktionen ohne React:
  6	//
  7	//   node src/lib/rechner/netzanschluss.js      → Selbsttest
  8	//
  9	// Grundlagen (DE): § 8 EEG (Anschlusspflicht, Netzverknüpfungspunkt, Fristen),
 10	// § 8a EEG (flexible Netzanschlussvereinbarung / Überbauung), § 16 EEG (Kosten
 11	// des Anschlusses bis zum Verknüpfungspunkt trägt der Anlagenbetreiber),
 12	// § 17 EEG (Kosten der Kapazitätserweiterung trägt der Netzbetreiber).
 13	// Ein Baukostenzuschuss fällt für reine Einspeiser in der Regel nicht an –
 14	// wohl aber für Netzbezug, etwa eines Speichers, der aus dem Netz lädt.
 15	// Kostenbausteine: FREIFLAECHE (+ .netz), SPEICHER.bkzProKw (markt.js).
 16	
 17	import { ERLOESE, FREIFLAECHE, REGIONEN, SPEICHER } from "../invest/markt.js";
 18	
 19	const N = FREIFLAECHE.netz;
 20	
 21	export const EBENEN = [
 22	  { id: "auto", label: "Automatisch", sub: "nach Leistung" },
 23	  { id: "msLeitung", label: "MS-Leitung", sub: "Einschleifen 20 kV" },
 24	  { id: "uwMs", label: "Umspannwerk", sub: "MS-Sammelschiene" },
 25	  { id: "hs", label: "110 kV", sub: "eigenes Umspannwerk" },
 26	];
 27	
 28	export const KAPAZITAETEN = [
 29	  { id: "frei", label: "Bekannt: frei", sub: "Auskunft liegt vor" },
 30	  { id: "unbekannt", label: "Unbekannt", sub: "noch nicht angefragt" },
 31	  { id: "knapp", label: "Bekannt: knapp", sub: "Ausbau nötig" },
 32	];
 33	
 34	export const LAENDER = [
 35	  { id: "de", label: "Deutschland" },
 36	  { id: "at", label: "Österreich" },
 37	  { id: "ch", label: "Schweiz" },
 38	];
 39	
 40	export const STANDARD = {
 41	  mwp: 10,
 42	  anschlussQuote: 1,
 43	  km: 2,
 44	  ebene: "auto",
 45	  kapazitaet: "unbekannt",
 46	  speicherMw: 0,
 47	  speicherNetzbezug: false,
 48	  cluster: false,
 49	  land: "de",
 50	};
 51	
 52	/** Spannweite der Kostenschätzung (Tiefbau, Querungen, Genehmigungen, Materialpreise) */
 53	export const SPANNE = { min: 0.8, max: 1.4 };
 54	/** Anteil gemeinsam genutzter Kosten (Trasse, Umspannwerk), die bei Clusterung mit einem Nachbarprojekt entfallen – eigene Annahme */
 55	export const CLUSTER_ANTEIL = 0.5;
 56	
 57	const ERTRAG_DE = Math.round(REGIONEN.filter((r) => r.land === "DE").reduce((s, r) => s + r.ertrag, 0) / REGIONEN.filter((r) => r.land === "DE").length);
 58	
 59	/** Energieverlust (Anteil) bei Anschlussleistung/Modulleistung – lineare Interpolation der Tabelle */
 60	export function abregelVerlust(quote) {
 61	  const t = N.abregelung;
 62	  if (quote >= t[0][0]) return 0;
 63	  for (let i = 1; i < t.length; i++) {
 64	    const [q1, v1] = t[i - 1];
 65	    const [q2, v2] = t[i];
 66	    if (quote >= q2) return v1 + ((q1 - quote) / (q1 - q2)) * (v2 - v1);
 67	  }
 68	  return t[t.length - 1][1];
 69	}
