export function selbsttest() {
  const fehler = [];
  const pruefe = (ok, text) => ok || fehler.push(text);

  const fest = pruefePachtangebot({ ha: 10, modell: "fest", proHa: 3000, indexArt: "keine", vorlaufJahre: 0, laufzeit: 30 });
